#!/usr/bin/env python3
from pathlib import Path
import subprocess
import textwrap
import chall

C_CODE = r'''
#include <stdio.h>
#include <gmp.h>

int main() {
    mpz_t n, seed, exp, y;
    mpz_inits(n, seed, exp, y, NULL);

    mpz_set_str(n, "", 10);

    mpz_set_str(seed, "", 10);

    // exp = 2^240000000
    mpz_set_ui(exp, 1);
    mpz_mul_2exp(exp, exp, 240000000UL);

    // y = seed^(2^rounds) mod n
    mpz_powm(y, seed, exp, n);

    mpz_out_str(stdout, 10, y);
    putchar('\n');

    mpz_clears(n, seed, exp, y, NULL);
    return 0;
}
'''

def main():
    c_path = Path("fast_timelock.c")
    bin_path = Path("fast_timelock")

    c_path.write_text(C_CODE)

    subprocess.check_call([
        "gcc",
        "-O3",
        "-march=native",
        str(c_path),
        "-lgmp",
        "-o",
        str(bin_path),
    ])

    print("[+] running GMP mpz_powm...")

    secret_raw = subprocess.check_output([f"./{bin_path}"]).strip()
    secret = int(secret_raw)

    values = chall.load_output(Path("output.txt"))

    pt = chall.decrypt(
        secret,
        values["n"],
        values["nonce"],
        values["ciphertext"],
        values["tag"],
    )

    print(f"<FLAG>{pt.decode()}</FLAG>")

if __name__ == "__main__":
    main()
